/**
 * TabsPro FSM - Finite State Machine for advanced tab behavior
 *
 * Manages per-tab state for:
 * - Async lazy loading (loadContent)
 * - Permission/guard gating
 * - Error states with retry
 * - Analytics hooks
 *
 * Each tab runs its own independent FSM instance.
 * This FSM is pure and testable - no React dependencies.
 *
 * @module TabsPro/FSM
 */

import type { ReactNode } from 'react';

const TAB_ID_PATTERN = /^[A-Za-z0-9._:-]+$/;

const isSafeTabId = (tabId: string): boolean => TAB_ID_PATTERN.test(tabId);

const getSafeTabState = (tabs: TabsProFSMStateMap, tabId: string): TabProFSMState | undefined => {
  if (!isSafeTabId(tabId)) {
    return undefined;
  }
  // eslint-disable-next-line security/detect-object-injection -- tabId validated via isSafeTabId
  return tabs[tabId];
};

const assignSafeTabState = (
  target: TabsProFSMStateMap,
  tabId: string,
  tabState: TabProFSMState
): void => {
  if (!isSafeTabId(tabId)) {
    return;
  }
  // eslint-disable-next-line security/detect-object-injection -- tabId validated via isSafeTabId
  target[tabId] = tabState;
};

// =============================================================================
// Types
// =============================================================================

/**
 * Per-tab FSM status values
 *
 * - idle: Tab is not active and has never loaded
 * - checkingGuard: Checking permissions/guard function
 * - blocked: Guard failed, user not allowed
 * - loading: Allowed, loading async content
 * - ready: Content loaded successfully
 * - error: Loading failed
 */
export type TabProStatus = 'idle' | 'checkingGuard' | 'blocked' | 'loading' | 'ready' | 'error';

/**
 * Guard check result
 */
export interface GuardResult {
  allowed: boolean;
  /** Reason for denial (for analytics/display) */
  reason?: string;
  /** Optional action label for CTA button */
  actionLabel?: string;
  /** Optional action callback */
  onAction?: () => void;
}

/**
 * Per-tab FSM state
 */
export interface TabProFSMState {
  /** Current status of this tab */
  status: TabProStatus;
  /** Loaded content (when status is 'ready') */
  loadedContent: ReactNode | null;
  /** Error information (when status is 'error') */
  error: unknown | null;
  /** Guard result (when status is 'blocked') */
  guardResult: GuardResult | null;
  /** Number of load attempts (for retry logic) */
  loadAttempts: number;
  /** Whether this tab has ever been activated */
  hasBeenActivated: boolean;
  /** Timestamp of last activation */
  lastActivatedAt: number | null;
}

/**
 * Map of tab states keyed by tab ID
 */
export type TabsProFSMStateMap = Record<string, TabProFSMState>;

/**
 * Combined FSM state for all tabs
 */
export interface TabsProFSMState {
  /** Map of per-tab states */
  tabs: TabsProFSMStateMap;
  /** Currently active tab ID */
  activeTabId: string | null;
  /** Previous active tab ID (for leave confirmation) */
  previousTabId: string | null;
  /** Whether we're waiting for leave confirmation */
  pendingLeaveConfirmation: boolean;
  /** Tab ID waiting to be activated after leave confirmation */
  pendingActivationId: string | null;
}

// =============================================================================
// Event Types
// =============================================================================

/**
 * Initialize tabs from config
 */
export interface InitializeTabsEvent {
  type: 'INITIALIZE_TABS';
  tabIds: string[];
  defaultActiveId?: string;
}

/**
 * User attempts to activate a tab
 */
export interface ActivateTabEvent {
  type: 'ACTIVATE_TAB';
  tabId: string;
  /** Whether to skip guard check (e.g., for retry) */
  skipGuard?: boolean;
}

/**
 * Guard check passed
 */
export interface GuardOkEvent {
  type: 'GUARD_OK';
  tabId: string;
}

/**
 * Guard check failed
 */
export interface GuardFailEvent {
  type: 'GUARD_FAIL';
  tabId: string;
  result: GuardResult;
}

/**
 * Start loading async content
 */
export interface LoadStartEvent {
  type: 'LOAD_START';
  tabId: string;
}

/**
 * Content loaded successfully
 */
export interface LoadSuccessEvent {
  type: 'LOAD_SUCCESS';
  tabId: string;
  content: ReactNode;
}

/**
 * Content loading failed
 */
export interface LoadErrorEvent {
  type: 'LOAD_ERROR';
  tabId: string;
  error: unknown;
}

/**
 * User requests retry after error
 */
export interface RetryEvent {
  type: 'RETRY';
  tabId: string;
}

/**
 * Request to leave current tab (for unsaved changes prompt)
 */
export interface LeaveRequestEvent {
  type: 'LEAVE_REQUEST';
  fromTabId: string;
  toTabId: string;
}

/**
 * User confirmed leaving (from unsaved changes prompt)
 */
export interface LeaveConfirmedEvent {
  type: 'LEAVE_CONFIRMED';
}

/**
 * User cancelled leaving (from unsaved changes prompt)
 */
export interface LeaveCancelledEvent {
  type: 'LEAVE_CANCELLED';
}

/**
 * Reset a tab to idle state
 */
export interface ResetTabEvent {
  type: 'RESET_TAB';
  tabId: string;
}

/**
 * Preload a tab (hover intent)
 */
export interface PreloadTabEvent {
  type: 'PRELOAD_TAB';
  tabId: string;
}

/**
 * Union of all FSM events
 */
export type TabsProFSMEvent =
  | InitializeTabsEvent
  | ActivateTabEvent
  | GuardOkEvent
  | GuardFailEvent
  | LoadStartEvent
  | LoadSuccessEvent
  | LoadErrorEvent
  | RetryEvent
  | LeaveRequestEvent
  | LeaveConfirmedEvent
  | LeaveCancelledEvent
  | ResetTabEvent
  | PreloadTabEvent;

// =============================================================================
// Initial State Factory
// =============================================================================

/**
 * Creates initial state for a single tab
 */
export function createInitialTabState(): TabProFSMState {
  return {
    status: 'idle',
    loadedContent: null,
    error: null,
    guardResult: null,
    loadAttempts: 0,
    hasBeenActivated: false,
    lastActivatedAt: null,
  };
}

/**
 * Creates initial FSM state for all tabs
 */
export function createInitialTabsProFSMState(
  tabIds: string[],
  defaultActiveId?: string
): TabsProFSMState {
  const tabs: TabsProFSMStateMap = {};

  for (const id of tabIds) {
    assignSafeTabState(tabs, id, createInitialTabState());
  }

  return {
    tabs,
    activeTabId: defaultActiveId ?? tabIds[0] ?? null,
    previousTabId: null,
    pendingLeaveConfirmation: false,
    pendingActivationId: null,
  };
}

// =============================================================================
// FSM Reducer
// =============================================================================

/**
 * Pure reducer for TabsPro FSM
 *
 * @param state - Current FSM state
 * @param event - Event to process
 * @returns New FSM state
 */
export function tabsProFSMReducer(state: TabsProFSMState, event: TabsProFSMEvent): TabsProFSMState {
  switch (event.type) {
    case 'INITIALIZE_TABS': {
      const { tabIds, defaultActiveId } = event;
      const tabs: TabsProFSMStateMap = {};

      for (const id of tabIds) {
        // Preserve existing tab state if it exists
        const existingState = getSafeTabState(state.tabs, id);
        assignSafeTabState(tabs, id, existingState ?? createInitialTabState());
      }

      return {
        ...state,
        tabs,
        activeTabId: defaultActiveId ?? tabIds[0] ?? state.activeTabId,
      };
    }

    case 'ACTIVATE_TAB': {
      const { tabId, skipGuard } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      // Tab doesn't exist
      if (!tabState) {
        return state;
      }

      // If pending leave confirmation, store the target tab
      if (state.pendingLeaveConfirmation) {
        return {
          ...state,
          pendingActivationId: tabId,
        };
      }

      // Update active tab
      const newTabs = { ...state.tabs };
      const now = Date.now();

      // Move to checkingGuard (or loading if skipGuard)
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: skipGuard ? 'loading' : 'checkingGuard',
        hasBeenActivated: true,
        lastActivatedAt: now,
      });

      return {
        ...state,
        tabs: newTabs,
        activeTabId: tabId,
        previousTabId: state.activeTabId,
      };
    }

    case 'GUARD_OK': {
      const { tabId } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      // Accept from idle or checkingGuard (idle happens when executeGuardAndLoad runs before ACTIVATE_TAB)
      if (!tabState || (tabState.status !== 'checkingGuard' && tabState.status !== 'idle')) {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'loading',
        guardResult: null,
      });

      return { ...state, tabs: newTabs };
    }

    case 'GUARD_FAIL': {
      const { tabId, result } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      // Accept from idle or checkingGuard (idle happens when executeGuardAndLoad runs before ACTIVATE_TAB)
      if (!tabState || (tabState.status !== 'checkingGuard' && tabState.status !== 'idle')) {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'blocked',
        guardResult: result,
      });

      return { ...state, tabs: newTabs };
    }

    case 'LOAD_START': {
      const { tabId } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      if (!tabState) {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'loading',
        loadAttempts: tabState.loadAttempts + 1,
      });

      return { ...state, tabs: newTabs };
    }

    case 'LOAD_SUCCESS': {
      const { tabId, content } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      // Accept from loading state; also allow from idle/checkingGuard for sync content paths
      if (!tabState) {
        return state;
      }

      // Only process if in a valid loading-related state
      const validStates: TabProStatus[] = ['idle', 'checkingGuard', 'loading'];
      if (!validStates.includes(tabState.status)) {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'ready',
        loadedContent: content,
        error: null,
      });

      return { ...state, tabs: newTabs };
    }

    case 'LOAD_ERROR': {
      const { tabId, error } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      // Accept from loading state; also allow from idle/checkingGuard for edge cases
      if (!tabState) {
        return state;
      }

      // Only process if in a valid loading-related state
      const validStates: TabProStatus[] = ['idle', 'checkingGuard', 'loading'];
      if (!validStates.includes(tabState.status)) {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'error',
        error,
      });

      return { ...state, tabs: newTabs };
    }

    case 'RETRY': {
      const { tabId } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      if (!tabState || tabState.status !== 'error') {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'loading',
        error: null,
      });

      return { ...state, tabs: newTabs };
    }

    case 'LEAVE_REQUEST': {
      const { fromTabId, toTabId } = event;

      return {
        ...state,
        pendingLeaveConfirmation: true,
        pendingActivationId: toTabId,
        previousTabId: fromTabId,
      };
    }

    case 'LEAVE_CONFIRMED': {
      const pendingId = state.pendingActivationId;

      if (!pendingId) {
        return {
          ...state,
          pendingLeaveConfirmation: false,
          pendingActivationId: null,
        };
      }

      // Activate the pending tab
      const tabState = pendingId ? getSafeTabState(state.tabs, pendingId) : undefined;
      if (!tabState) {
        return {
          ...state,
          pendingLeaveConfirmation: false,
          pendingActivationId: null,
        };
      }

      const newTabs = { ...state.tabs };
      const now = Date.now();

      assignSafeTabState(newTabs, pendingId, {
        ...tabState,
        status: 'checkingGuard',
        hasBeenActivated: true,
        lastActivatedAt: now,
      });

      return {
        ...state,
        tabs: newTabs,
        activeTabId: pendingId,
        pendingLeaveConfirmation: false,
        pendingActivationId: null,
      };
    }

    case 'LEAVE_CANCELLED': {
      return {
        ...state,
        pendingLeaveConfirmation: false,
        pendingActivationId: null,
      };
    }

    case 'RESET_TAB': {
      const { tabId } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      if (!tabState) {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, createInitialTabState());

      return { ...state, tabs: newTabs };
    }

    case 'PRELOAD_TAB': {
      const { tabId } = event;
      const tabState = getSafeTabState(state.tabs, tabId);

      // Only preload if tab is idle
      if (!tabState || tabState.status !== 'idle') {
        return state;
      }

      const newTabs = { ...state.tabs };
      assignSafeTabState(newTabs, tabId, {
        ...tabState,
        status: 'checkingGuard',
      });

      return { ...state, tabs: newTabs };
    }

    default:
      return state;
  }
}

/**
 * Creates an INITIALIZE_TABS event
 */
export function initializeTabsEvent(
  tabIds: string[],
  defaultActiveId?: string
): InitializeTabsEvent {
  return { type: 'INITIALIZE_TABS', tabIds, defaultActiveId };
}

/**
 * Creates an ACTIVATE_TAB event
 */
export function activateTabEvent(tabId: string, skipGuard = false): ActivateTabEvent {
  return { type: 'ACTIVATE_TAB', tabId, skipGuard };
}

/**
 * Creates a GUARD_OK event
 */
export function guardOkEvent(tabId: string): GuardOkEvent {
  return { type: 'GUARD_OK', tabId };
}

/**
 * Creates a GUARD_FAIL event
 */
export function guardFailEvent(tabId: string, result: GuardResult): GuardFailEvent {
  return { type: 'GUARD_FAIL', tabId, result };
}

/**
 * Creates a LOAD_START event
 */
export function loadStartEvent(tabId: string): LoadStartEvent {
  return { type: 'LOAD_START', tabId };
}

/**
 * Creates a LOAD_SUCCESS event
 */
export function loadSuccessEvent(tabId: string, content: ReactNode): LoadSuccessEvent {
  return { type: 'LOAD_SUCCESS', tabId, content };
}

/**
 * Creates a LOAD_ERROR event
 */
export function loadErrorEvent(tabId: string, error: unknown): LoadErrorEvent {
  return { type: 'LOAD_ERROR', tabId, error };
}

/**
 * Creates a RETRY event
 */
export function retryEvent(tabId: string): RetryEvent {
  return { type: 'RETRY', tabId };
}

/**
 * Creates a LEAVE_REQUEST event
 */
export function leaveRequestEvent(fromTabId: string, toTabId: string): LeaveRequestEvent {
  return { type: 'LEAVE_REQUEST', fromTabId, toTabId };
}

/**
 * Creates a LEAVE_CONFIRMED event
 */
export function leaveConfirmedEvent(): LeaveConfirmedEvent {
  return { type: 'LEAVE_CONFIRMED' };
}

/**
 * Creates a LEAVE_CANCELLED event
 */
export function leaveCancelledEvent(): LeaveCancelledEvent {
  return { type: 'LEAVE_CANCELLED' };
}

/**
 * Creates a RESET_TAB event
 */
export function resetTabEvent(tabId: string): ResetTabEvent {
  return { type: 'RESET_TAB', tabId };
}

/**
 * Creates a PRELOAD_TAB event
 */
export function preloadTabEvent(tabId: string): PreloadTabEvent {
  return { type: 'PRELOAD_TAB', tabId };
}

// =============================================================================
// Predicates
// =============================================================================

/**
 * Check if a tab is in idle state
 */
export function isTabIdle(state: TabsProFSMState, tabId: string): boolean {
  return getSafeTabState(state.tabs, tabId)?.status === 'idle';
}

/**
 * Check if a tab is checking guard
 */
export function isTabCheckingGuard(state: TabsProFSMState, tabId: string): boolean {
  return getSafeTabState(state.tabs, tabId)?.status === 'checkingGuard';
}

/**
 * Check if a tab is blocked
 */
export function isTabBlocked(state: TabsProFSMState, tabId: string): boolean {
  return getSafeTabState(state.tabs, tabId)?.status === 'blocked';
}

/**
 * Check if a tab is loading
 */
export function isTabLoading(state: TabsProFSMState, tabId: string): boolean {
  return getSafeTabState(state.tabs, tabId)?.status === 'loading';
}

/**
 * Check if a tab is ready
 */
export function isTabReady(state: TabsProFSMState, tabId: string): boolean {
  return getSafeTabState(state.tabs, tabId)?.status === 'ready';
}

/**
 * Check if a tab has error
 */
export function isTabError(state: TabsProFSMState, tabId: string): boolean {
  return getSafeTabState(state.tabs, tabId)?.status === 'error';
}

/**
 * Check if a tab is the active tab
 */
export function isTabActive(state: TabsProFSMState, tabId: string): boolean {
  return state.activeTabId === tabId;
}

/**
 * Check if leave confirmation is pending
 */
export function isLeaveConfirmationPending(state: TabsProFSMState): boolean {
  return state.pendingLeaveConfirmation;
}

/**
 * Get the tab state for a specific tab
 */
export function getTabState(state: TabsProFSMState, tabId: string): TabProFSMState | undefined {
  return getSafeTabState(state.tabs, tabId);
}

/**
 * Get the active tab state
 */
export function getActiveTabState(state: TabsProFSMState): TabProFSMState | undefined {
  if (!state.activeTabId) {
    return undefined;
  }
  return getSafeTabState(state.tabs, state.activeTabId);
}

/**
 * Get the loaded content for a tab
 */
export function getTabContent(state: TabsProFSMState, tabId: string): ReactNode | null {
  return getSafeTabState(state.tabs, tabId)?.loadedContent ?? null;
}

/**
 * Get the error for a tab
 */
export function getTabError(state: TabsProFSMState, tabId: string): unknown | null {
  return getSafeTabState(state.tabs, tabId)?.error ?? null;
}

/**
 * Get the guard result for a tab
 */
export function getTabGuardResult(state: TabsProFSMState, tabId: string): GuardResult | null {
  return getSafeTabState(state.tabs, tabId)?.guardResult ?? null;
}

/**
 * TabsPro Component
 *
 * Advanced tab system with FSM-based state management supporting:
 * - Async lazy loading with loading states
 * - Permission/guard gating with blocked states
 * - Error states with retry functionality
 * - Analytics hooks for tracking
 * - Dirty/unsaved changes confirmation
 *
 * Wraps the existing Tabs component - does not modify it.
 *
 * @see https://getbootstrap.com/docs/5.3/components/navs-tabs/
 * @packageDocumentation
 */

import {
  forwardRef,
  memo,
  useCallback,
  useEffect,
  useId,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';

import { Tabs } from '../Tabs/Tabs';

import {
  activateTabEvent,
  createInitialTabsProFSMState,
  guardFailEvent,
  guardOkEvent,
  initializeTabsEvent,
  leaveCancelledEvent,
  leaveConfirmedEvent,
  leaveRequestEvent,
  loadErrorEvent,
  loadSuccessEvent,
  retryEvent,
  tabsProFSMReducer,
} from './TabsPro.fsm';

import type { GuardResult } from './TabsPro.fsm';
import type {
  DefaultBlockedProps,
  DefaultErrorProps,
  DefaultLoadingProps,
  ResolvedTabItem,
  TabsProItem,
  TabsProProps,
} from './TabsPro.types';
import type { TabItem } from '../Tabs/Tabs.types';

// =============================================================================
// Default Fallback Components
// =============================================================================

/**
 * Default loading spinner component
 */
const DefaultLoading = memo(function DefaultLoading({
  message = 'Loading...',
}: DefaultLoadingProps) {
  return (
    <output
      className="d-flex flex-column align-items-center justify-content-center p-4"
      aria-live="polite"
    >
      <div className="spinner-border text-primary mb-2" aria-hidden="true">
        <span className="visually-hidden">Loading</span>
      </div>
      <span className="text-muted">{message}</span>
    </output>
  );
});

DefaultLoading.displayName = 'DefaultLoading';

/**
 * Default blocked/access denied component
 */
const DefaultBlocked = memo(function DefaultBlocked({
  title = 'Access Restricted',
  description = 'You do not have permission to view this content.',
  actionLabel,
  onAction,
}: DefaultBlockedProps) {
  return (
    <div className="d-flex flex-column align-items-center justify-content-center p-4 text-center">
      <div className="mb-3">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="48"
          height="48"
          fill="currentColor"
          className="text-warning"
          viewBox="0 0 16 16"
          aria-hidden="true"
        >
          <path d="M8 1a2 2 0 0 1 2 2v4H6V3a2 2 0 0 1 2-2m3 6V3a3 3 0 0 0-6 0v4a2 2 0 0 0-2 2v5a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2" />
        </svg>
      </div>
      <h5 className="mb-2">{title}</h5>
      <p className="text-muted mb-3">{description}</p>
      {actionLabel && onAction && (
        <button type="button" className="btn btn-outline-primary" onClick={onAction}>
          {actionLabel}
        </button>
      )}
    </div>
  );
});

DefaultBlocked.displayName = 'DefaultBlocked';

/**
 * Default error component with retry button
 */
const DefaultError = memo(function DefaultError({
  message = 'Failed to load content.',
  onRetry,
}: DefaultErrorProps) {
  return (
    <div
      className="d-flex flex-column align-items-center justify-content-center p-4 text-center"
      role="alert"
    >
      <div className="mb-3">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="48"
          height="48"
          fill="currentColor"
          className="text-danger"
          viewBox="0 0 16 16"
          aria-hidden="true"
        >
          <path d="M8.982 1.566a1.13 1.13 0 0 0-1.96 0L.165 13.233c-.457.778.091 1.767.98 1.767h13.713c.889 0 1.438-.99.98-1.767zM8 5c.535 0 .954.462.9.995l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 5.995A.905.905 0 0 1 8 5m.002 6a1 1 0 1 1 0 2 1 1 0 0 1 0-2" />
        </svg>
      </div>
      <h5 className="mb-2">Something went wrong</h5>
      <p className="text-muted mb-3">{message}</p>
      <button type="button" className="btn btn-primary" onClick={onRetry}>
        Try again
      </button>
    </div>
  );
});

DefaultError.displayName = 'DefaultError';

/**
 * Leave confirmation modal component
 */
interface LeaveConfirmModalProps {
  show: boolean;
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
}

const LeaveConfirmModal = memo(function LeaveConfirmModal({
  show,
  message,
  onConfirm,
  onCancel,
  titleId,
}: LeaveConfirmModalProps & { titleId: string }) {
  if (!show) {
    return null;
  }

  return (
    <div
      className="modal d-block"
      style={{ backgroundColor: 'rgba(0, 0, 0, 0.5)' }}
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
    >
      <div className="modal-dialog modal-dialog-centered">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title" id={titleId}>
              Unsaved Changes
            </h5>
            <button type="button" className="btn-close" aria-label="Close" onClick={onCancel} />
          </div>
          <div className="modal-body">
            <p>{message}</p>
          </div>
          <div className="modal-footer">
            <button type="button" className="btn btn-secondary" onClick={onCancel}>
              Stay
            </button>
            <button type="button" className="btn btn-danger" onClick={onConfirm}>
              Leave
            </button>
          </div>
        </div>
      </div>
    </div>
  );
});

LeaveConfirmModal.displayName = 'LeaveConfirmModal';

// =============================================================================
// TabsPro Component
// =============================================================================

/**
 * TabsPro - Advanced tabs with async loading, permission gating, and analytics
 *
 * @example Basic async loading
 * ```tsx
 * <TabsPro
 *   items={[
 *     {
 *       id: 'reports',
 *       label: 'Reports',
 *       loadContent: async () => <ReportsPanel />,
 *     },
 *     {
 *       id: 'settings',
 *       label: 'Settings',
 *       content: <SettingsPanel />,
 *     },
 *   ]}
 * />
 * ```
 *
 * @example Permission-gated tab
 * ```tsx
 * <TabsPro
 *   items={[
 *     {
 *       id: 'admin',
 *       label: 'Admin',
 *       guard: async () => ({
 *         allowed: user.isAdmin,
 *         reason: 'not-admin',
 *       }),
 *       blockedFallback: <AdminBlockedMessage />,
 *       loadContent: async () => <AdminPanel />,
 *     },
 *   ]}
 * />
 * ```
 */
export const TabsPro = memo(
  forwardRef<HTMLDivElement, TabsProProps>(function TabsPro(
    {
      items,
      activeId: controlledActiveId,
      defaultActiveId,
      onActiveChange,
      keepMounted: _keepMounted = false,
      variant = 'tabs',
      orientation = 'horizontal',
      fill = false,
      justified = false,
      isDirty,
      dirtyConfirmMessage = 'You have unsaved changes. Leave without saving?',
      onDirtyLeave,
      onDirtyStay,
      className,
      style,
      id,
      defaultLoadingFallback,
      defaultBlockedFallback,
      defaultErrorFallback,
    },
    ref
  ) {
    // =========================================================================
    // FSM State
    // =========================================================================

    const tabIds = useMemo(() => items.map((item) => item.id), [items]);
    const initialActiveId = controlledActiveId ?? defaultActiveId ?? tabIds[0];

    const [fsmState, dispatch] = useReducer(
      tabsProFSMReducer,
      { tabIds, defaultActiveId: initialActiveId },
      (init) => createInitialTabsProFSMState(init.tabIds, init.defaultActiveId)
    );

    // Track items by ID for quick lookup
    const itemsMap = useMemo(() => {
      const map = new Map<string, TabsProItem>();
      for (const item of items) {
        map.set(item.id, item);
      }
      return map;
    }, [items]);

    // Track controlled mode
    const isControlled = controlledActiveId !== undefined;
    const [internalActiveId, setInternalActiveId] = useState(initialActiveId);
    const activeId = isControlled ? controlledActiveId : internalActiveId;

    // Ref to track loading promises to avoid race conditions
    const loadingPromises = useRef<Map<string, Promise<void>>>(new Map());

    // Generate unique ID for modal title
    const leaveConfirmTitleId = useId();

    // =========================================================================
    // Sync FSM with tab changes
    // =========================================================================

    useEffect(() => {
      dispatch(initializeTabsEvent(tabIds, activeId ?? undefined));
    }, [tabIds, activeId]);

    // =========================================================================
    // Guard and Load Logic
    // =========================================================================

    const executeGuardAndLoad = useCallback(
      async (tabId: string) => {
        const item = itemsMap.get(tabId);
        if (!item) {
          return;
        }

        // Check guard
        if (item.guard) {
          try {
            const result = await Promise.resolve(item.guard());

            if (!result.allowed) {
              dispatch(guardFailEvent(tabId, result));
              item.onGuardFail?.({ id: tabId, reason: result.reason });
              return;
            }

            dispatch(guardOkEvent(tabId));
          } catch {
            // Guard threw an error - treat as blocked
            const guardResult: GuardResult = {
              allowed: false,
              reason: 'guard-error',
            };
            dispatch(guardFailEvent(tabId, guardResult));
            item.onGuardFail?.({ id: tabId, reason: 'guard-error' });
            return;
          }
        } else {
          // No guard - proceed directly
          dispatch(guardOkEvent(tabId));
        }

        // Load content
        const loader = item.loadContent;
        if (loader) {
          // Check if already loading
          if (loadingPromises.current.has(tabId)) {
            return;
          }

          const loadPromise = (async () => {
            try {
              const content = await loader();
              dispatch(loadSuccessEvent(tabId, content));
              item.onViewed?.();
            } catch (error) {
              dispatch(loadErrorEvent(tabId, error));
              item.onError?.(error);
            } finally {
              loadingPromises.current.delete(tabId);
            }
          })();

          loadingPromises.current.set(tabId, loadPromise);
        } else {
          // No async loader - use static content, mark as ready
          dispatch(loadSuccessEvent(tabId, item.content ?? null));
          item.onViewed?.();
        }
      },
      [itemsMap]
    );

    // Create a Map for safe tab state lookup
    const tabsStateMap = useMemo(() => {
      const tabs = fsmState.tabs;
      const map = new Map<string, (typeof tabs)[string]>();
      for (const [key, value] of Object.entries(tabs)) {
        map.set(key, value);
      }
      return map;
    }, [fsmState.tabs]);

    // =========================================================================
    // Tab Change Handler
    // =========================================================================

    const handleTabChange = useCallback(
      (newTabId: string) => {
        const currentTabId = fsmState.activeTabId;

        // Check for dirty state
        if (currentTabId && isDirty?.(currentTabId)) {
          dispatch(leaveRequestEvent(currentTabId, newTabId));
          return;
        }

        // Activate tab
        const item = itemsMap.get(newTabId);
        item?.onActivate?.();

        dispatch(activateTabEvent(newTabId));

        if (!isControlled) {
          setInternalActiveId(newTabId);
        }
        onActiveChange?.(newTabId);

        // Start guard/load process
        // Safe access using Map
        const tabState = tabsStateMap.get(newTabId);
        if (tabState && (tabState.status === 'idle' || tabState.status === 'checkingGuard')) {
          executeGuardAndLoad(newTabId);
        }
      },
      [
        fsmState.activeTabId,
        isDirty,
        itemsMap,
        isControlled,
        onActiveChange,
        executeGuardAndLoad,
        tabsStateMap,
      ]
    );

    // =========================================================================
    // Leave Confirmation Handlers
    // =========================================================================

    const handleLeaveConfirm = useCallback(() => {
      const fromId = fsmState.previousTabId;
      const toId = fsmState.pendingActivationId;

      if (fromId && toId) {
        onDirtyLeave?.(fromId, toId);
      }

      dispatch(leaveConfirmedEvent());

      if (toId) {
        if (!isControlled) {
          setInternalActiveId(toId);
        }
        onActiveChange?.(toId);
        executeGuardAndLoad(toId);
      }
    }, [fsmState, isControlled, onActiveChange, onDirtyLeave, executeGuardAndLoad]);

    const handleLeaveCancel = useCallback(() => {
      if (fsmState.previousTabId) {
        onDirtyStay?.(fsmState.previousTabId);
      }
      dispatch(leaveCancelledEvent());
    }, [fsmState.previousTabId, onDirtyStay]);

    // =========================================================================
    // Retry Handler
    // =========================================================================

    const handleRetry = useCallback(
      (tabId: string) => {
        dispatch(retryEvent(tabId));
        executeGuardAndLoad(tabId);
      },
      [executeGuardAndLoad]
    );

    // =========================================================================
    // Initial Load Effect - Run once after mount
    // =========================================================================

    const hasInitializedRef = useRef(false);

    useEffect(() => {
      // Only run once - set immediately to prevent re-runs
      if (hasInitializedRef.current) {
        return;
      }
      hasInitializedRef.current = true;

      // Trigger guard/load for initial active tab
      if (activeId) {
        executeGuardAndLoad(activeId);
      }
    }, [activeId, executeGuardAndLoad]);

    // =========================================================================
    // Resolve Tab Content Based on FSM State
    // =========================================================================

    const resolvedItems = useMemo<ResolvedTabItem[]>(() => {
      return items.map((item) => {
        // Safe access using Map
        const tabState = tabsStateMap.get(item.id);
        const status = tabState?.status ?? 'idle';

        let content: React.ReactNode;

        switch (status) {
          case 'blocked': {
            const guardResult = tabState?.guardResult;
            if (item.blockedFallback) {
              content = item.blockedFallback;
            } else if (defaultBlockedFallback) {
              content = defaultBlockedFallback;
            } else {
              content = (
                <DefaultBlocked
                  title="Access Restricted"
                  description={
                    guardResult?.reason ?? 'You do not have permission to view this content.'
                  }
                  actionLabel={guardResult?.actionLabel}
                  onAction={guardResult?.onAction}
                />
              );
            }
            break;
          }

          case 'loading':
          case 'checkingGuard': {
            if (item.loadingFallback) {
              content = item.loadingFallback;
            } else if (defaultLoadingFallback) {
              content = defaultLoadingFallback;
            } else {
              content = <DefaultLoading message="Loading..." />;
            }
            break;
          }

          case 'error': {
            const error = tabState?.error;
            const retry = (): void => handleRetry(item.id);

            if (item.errorFallback) {
              content = item.errorFallback(error, retry);
            } else if (defaultErrorFallback) {
              content = defaultErrorFallback(error, retry);
            } else {
              content = (
                <DefaultError
                  message={error instanceof Error ? error.message : 'Failed to load content.'}
                  onRetry={retry}
                />
              );
            }
            break;
          }

          case 'ready': {
            content = tabState?.loadedContent ?? item.content ?? null;
            break;
          }
          default: {
            // Show loading for idle tabs when active (will trigger load)
            if (fsmState.activeTabId === item.id) {
              if (item.loadingFallback) {
                content = item.loadingFallback;
              } else if (defaultLoadingFallback) {
                content = defaultLoadingFallback;
              } else {
                content = <DefaultLoading message="Loading..." />;
              }
            } else {
              // Not active - show nothing or static content
              content = item.content ?? null;
            }
            break;
          }
        }

        return {
          id: item.id,
          label: item.label,
          icon: item.icon,
          disabled: item.disabled,
          content,
        };
      });
    }, [
      items,
      tabsStateMap,
      fsmState,
      handleRetry,
      defaultLoadingFallback,
      defaultBlockedFallback,
      defaultErrorFallback,
    ]);

    // =========================================================================
    // Convert to Tabs items format
    // =========================================================================

    const tabItems = useMemo<TabItem[]>(() => {
      return resolvedItems.map((item) => ({
        id: item.id,
        label: item.label,
        icon: item.icon,
        disabled: item.disabled,
        content: item.content,
      }));
    }, [resolvedItems]);

    // =========================================================================
    // Render
    // =========================================================================

    return (
      <>
        <Tabs
          ref={ref}
          items={tabItems}
          activeTab={activeId ?? undefined}
          onTabChange={handleTabChange}
          variant={variant}
          orientation={orientation}
          fill={fill}
          justified={justified}
          className={className}
          style={style}
          id={id}
        />

        <LeaveConfirmModal
          show={fsmState.pendingLeaveConfirmation}
          message={dirtyConfirmMessage}
          onConfirm={handleLeaveConfirm}
          onCancel={handleLeaveCancel}
          titleId={leaveConfirmTitleId}
        />
      </>
    );
  })
);

TabsPro.displayName = 'TabsPro';

// =============================================================================
// Exports
// =============================================================================

export type {
  AsyncLoader,
  DefaultBlockedProps,
  DefaultErrorProps,
  DefaultLoadingProps,
  GuardFn,
  GuardResult,
  ResolvedTabItem,
  TabsProItem,
  TabsProProps,
} from './TabsPro.types';

/**
 * TabsPro Types
 *
 * Type definitions for the TabsPro component - an advanced tab system
 * with FSM-based async loading, permission gating, and analytics.
 *
 * @module TabsPro/types
 */

import type { TabsOrientation, TabsVariant } from '../Tabs/Tabs.types';
import type { CSSProperties, ReactNode } from 'react';

// =============================================================================
// Guard Types
// =============================================================================

/**
 * Result of a guard/permission check
 */
export interface GuardResult {
  /** Whether access is allowed */
  allowed: boolean;
  /** Reason for denial (for analytics/display) */
  reason?: string;
  /** Optional action label for CTA button (e.g., "Upgrade", "Contact Admin") */
  actionLabel?: string;
  /** Optional action callback when CTA is clicked */
  onAction?: () => void;
}

/**
 * Guard function type - can be sync or async
 */
export type GuardFn = () => GuardResult | Promise<GuardResult>;

// =============================================================================
// Loader Types
// =============================================================================

/**
 * Async content loader function
 */
export type AsyncLoader<T = ReactNode> = () => Promise<T>;

// =============================================================================
// Tab Item Types
// =============================================================================

/**
 * Configuration for a single tab in TabsPro
 */
export interface TabsProItem {
  /**
   * Unique identifier for the tab
   */
  id: string;

  /**
   * Tab label displayed in the tab header
   */
  label: ReactNode;

  /**
   * Icon to display before the label
   */
  icon?: ReactNode;

  /**
   * Whether the tab is disabled
   * @default false
   */
  disabled?: boolean;

  // =========================================================================
  // Permission / Gating
  // =========================================================================

  /**
   * Guard function to check permissions before showing content.
   * Return { allowed: true } to proceed, or { allowed: false, reason: '...' } to block.
   * If not provided, tab is always allowed.
   */
  guard?: GuardFn;

  /**
   * Fallback content shown when guard fails (blocked state).
   * If not provided, a default blocked message is shown.
   */
  blockedFallback?: ReactNode;

  /**
   * Callback fired when guard check fails
   */
  onGuardFail?: (info: { id: string; reason?: string }) => void;

  // =========================================================================
  // Lazy Loading
  // =========================================================================

  /**
   * Async function to load tab content.
   * Content is loaded when tab is first activated.
   * If not provided, uses static `content` prop.
   */
  loadContent?: AsyncLoader<ReactNode>;

  /**
   * Whether to preload content on hover intent.
   * @default false
   */
  preloadOnHover?: boolean;

  /**
   * Loading indicator shown while content is loading.
   * If not provided, a default spinner is shown.
   */
  loadingFallback?: ReactNode;

  /**
   * Error fallback shown when loading fails.
   * If not provided, a default error UI with retry button is shown.
   * Receives error and retry callback.
   */
  errorFallback?: (error: unknown, retry: () => void) => ReactNode;

  // =========================================================================
  // Analytics / Hooks
  // =========================================================================

  /**
   * Callback fired when tab is successfully viewed (after guard and load)
   */
  onViewed?: () => void;

  /**
   * Callback fired when loading fails
   */
  onError?: (error: unknown) => void;

  /**
   * Callback fired when tab activation starts
   */
  onActivate?: () => void;

  // =========================================================================
  // Static Content
  // =========================================================================

  /**
   * Static content for non-async tabs.
   * Used when `loadContent` is not provided.
   */
  content?: ReactNode;
}

// =============================================================================
// Component Props
// =============================================================================

/**
 * Props for the TabsPro component
 */
export interface TabsProProps {
  /**
   * Tab items configuration
   */
  items: TabsProItem[];

  /**
   * Currently active tab ID (controlled mode)
   */
  activeId?: string;

  /**
   * Default active tab ID (uncontrolled mode)
   */
  defaultActiveId?: string;

  /**
   * Callback when active tab changes
   */
  onActiveChange?: (id: string | null) => void;

  /**
   * Whether to keep panel content mounted when inactive.
   * Useful for preserving state in tab panels.
   * @default false
   */
  keepMounted?: boolean;

  /**
   * Tab visual variant
   * @default 'tabs'
   */
  variant?: TabsVariant;

  /**
   * Tab orientation
   * @default 'horizontal'
   */
  orientation?: TabsOrientation;

  /**
   * Fill available width
   * @default false
   */
  fill?: boolean;

  /**
   * Justify tabs evenly
   * @default false
   */
  justified?: boolean;

  // =========================================================================
  // Dirty/Unsaved Changes
  // =========================================================================

  /**
   * Function to check if current tab has unsaved changes.
   * If returns true, a confirmation prompt is shown before switching.
   */
  isDirty?: (tabId: string) => boolean;

  /**
   * Custom confirmation message for unsaved changes
   * @default "You have unsaved changes. Leave without saving?"
   */
  dirtyConfirmMessage?: string;

  /**
   * Callback when user confirms leaving a dirty tab
   */
  onDirtyLeave?: (fromTabId: string, toTabId: string) => void;

  /**
   * Callback when user cancels leaving a dirty tab
   */
  onDirtyStay?: (tabId: string) => void;

  // =========================================================================
  // Styling
  // =========================================================================

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * ID attribute
   */
  id?: string;

  // =========================================================================
  // Default Fallbacks
  // =========================================================================

  /**
   * Default loading indicator for all tabs.
   * Can be overridden per-tab with `loadingFallback`.
   */
  defaultLoadingFallback?: ReactNode;

  /**
   * Default blocked message for all tabs.
   * Can be overridden per-tab with `blockedFallback`.
   */
  defaultBlockedFallback?: ReactNode;

  /**
   * Default error fallback for all tabs.
   * Can be overridden per-tab with `errorFallback`.
   */
  defaultErrorFallback?: (error: unknown, retry: () => void) => ReactNode;
}

// =============================================================================
// Internal Types
// =============================================================================

/**
 * Internal tab item with resolved content based on FSM state
 */
export interface ResolvedTabItem {
  id: string;
  label: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
  content: ReactNode;
}

/**
 * Props for the default loading component
 */
export interface DefaultLoadingProps {
  /** Loading message */
  message?: string;
}

/**
 * Props for the default blocked component
 */
export interface DefaultBlockedProps {
  /** Title message */
  title?: string;
  /** Description message */
  description?: string;
  /** Action button label */
  actionLabel?: string;
  /** Action button callback */
  onAction?: () => void;
}

/**
 * Props for the default error component
 */
export interface DefaultErrorProps {
  /** Error message */
  message?: string;
  /** Retry callback */
  onRetry: () => void;
}
